import{_ as r,C as o,o as t,c as s,a0 as i,b as l,w as a,a as c,E as d,a1 as p}from"./chunks/framework.DYS8d9tm.js";const k=JSON.parse('{"title":"Unified Parsing & Ingestion Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"technical/data ingestion/unified_parsing_pipeline.md","filePath":"technical/data ingestion/unified_parsing_pipeline.md"}'),g={name:"technical/data ingestion/unified_parsing_pipeline.md"};function u(h,e,m,b,y,f){const n=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=i('<h1 id="unified-parsing-ingestion-pipeline" tabindex="-1">Unified Parsing &amp; Ingestion Pipeline <a class="header-anchor" href="#unified-parsing-ingestion-pipeline" aria-label="Permalink to &quot;Unified Parsing &amp; Ingestion Pipeline&quot;">​</a></h1><p>This document details the stateless, multi-tiered parsing strategy and two-tier deduplication architecture used to process raw financial data (SMS, Email, Statements, and CAS).</p><hr><h2 id="_1-stateless-architecture-execution-hierarchy" tabindex="-1">1. Stateless Architecture &amp; Execution Hierarchy <a class="header-anchor" href="#_1-stateless-architecture-execution-hierarchy" aria-label="Permalink to &quot;1. Stateless Architecture &amp; Execution Hierarchy&quot;">​</a></h2><p>The Financial Parser Microservice (<code>Parser</code>, port <code>8001</code>) operates as a <strong>100% stateless, in-memory stream processor</strong>. It persists zero transactional data, zero customer PII, and zero database tables at rest.</p>',5)),(t(),l(p,null,{default:a(()=>[d(n,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Raw%20Message%20%2F%20File%20Input%22%5D%20--%3E%20B%5B%221.%20Classification%20Heuristic%20(FinancialClassifier)%22%5D%0A%20%20%20%20B%20--%3E%7C%22Non-Financial%20%2F%20OTP%20%2F%20Promo%22%7C%20C%5B%22Fast%20Return%3A%20status%3Dignored%20(0ms%20disk%20I%2FO)%22%5D%0A%20%20%20%20B%20--%3E%7C%22Financial%20Alert%22%7C%20D%5B%222.%20Fast%20Idempotency%20Guard%20(RecentSubmissionCache)%22%5D%0A%20%20%20%20D%20--%3E%7C%22Duplicate%20within%205-min%20TTL%22%7C%20E%5B%22Fast%20Return%3A%20status%3Dduplicate_submission%22%5D%0A%20%20%20%20D%20--%3E%7C%22Unique%20Payload%22%7C%20F%5B%223.%20Compiled%20Native%20Bank%20Registry%20(ParserRegistry)%22%5D%0A%20%20%20%20F%20--%3E%7C%2223%2B%20Major%20Indian%20Banks%22%7C%20G%5B%22Deterministic%20Extraction%20(%3E95%25%20confidence)%22%5D%0A%20%20%20%20F%20--%3E%7C%22Unstructured%20Statement%20%2F%20File%22%7C%20H%5B%22Universal%20%2F%20CAS%20%2F%20Statement%20Extractor%22%5D%0A%20%20%20%20G%20%26%20H%20--%3E%20I%5B%22Normalized%20Standardized%20JSON%20Schema%22%5D%0A%20%20%20%20I%20--%3E%20J%5B%22Ship%20Scrubbed%20Telemetry%20to%20Admin%20DuckDB%20(Async%20Queue)%22%5D%0A%20%20%20%20I%20--%3E%20K%5B%22Return%20IngestionResult%20to%20Backend%20Caller%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h3 id="parsing-hierarchy-priority-stack" tabindex="-1">Parsing Hierarchy (Priority Stack) <a class="header-anchor" href="#parsing-hierarchy-priority-stack" aria-label="Permalink to &quot;Parsing Hierarchy (Priority Stack)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Priority</th><th style="text-align:left;">Layer</th><th style="text-align:left;">Implementation</th><th style="text-align:left;">Speed</th><th style="text-align:left;">Confidence</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1</strong></td><td style="text-align:left;"><strong>Compiled Bank Registry</strong></td><td style="text-align:left;">Native Python parsers for 33+ Indian banks, SFBs &amp; fintechs (HDFC, ICICI, SBI, Axis, Kotak, SCB, HSBC, DBS, OneCard, Airtel Payments Bank, Equitas, CRED, BOM, IOB, UCO, etc.) with 150+ compiled regexes.</td><td style="text-align:left;">&lt; 0.5 ms</td><td style="text-align:left;">95%+</td></tr><tr><td style="text-align:left;"><strong>2</strong></td><td style="text-align:left;"><strong>Statement &amp; CAS Extractors</strong></td><td style="text-align:left;">Specialized table and transaction extractors (<code>pdfplumber</code>, <code>casparser</code>, <code>UniversalParser</code>).</td><td style="text-align:left;">10–50 ms</td><td style="text-align:left;">95%+</td></tr><tr><td style="text-align:left;"><strong>3</strong></td><td style="text-align:left;"><strong>Heuristic Normalizers</strong></td><td style="text-align:left;">Fast-fuzz merchant alias normalization (<code>rapidfuzz</code> in-memory), safe decimal conversion, and date extraction.</td><td style="text-align:left;">&lt; 0.1 ms</td><td style="text-align:left;">90%</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>All runtime dependencies on external AI/LLMs (such as Gemini) have been retired in favor of high-performance, deterministic compiled Python parsers. This guarantees sub-millisecond parsing latencies, zero cloud API costs, and full offline resilience.</p></div><hr><h2 id="_2-two-tier-deduplication-architecture" tabindex="-1">2. Two-Tier Deduplication Architecture <a class="header-anchor" href="#_2-two-tier-deduplication-architecture" aria-label="Permalink to &quot;2. Two-Tier Deduplication Architecture&quot;">​</a></h2><p>Deduplication operates across two strictly decoupled layers to ensure maximum throughput without losing any financial integrity:</p><h3 id="tier-1-ingestion-network-idempotency-parser-in-memory-lru" tabindex="-1">Tier 1: Ingestion Network Idempotency (Parser In-Memory LRU) <a class="header-anchor" href="#tier-1-ingestion-network-idempotency-parser-in-memory-lru" aria-label="Permalink to &quot;Tier 1: Ingestion Network Idempotency (Parser In-Memory LRU)&quot;">​</a></h3><ul><li><strong>Component</strong>: <code>RecentSubmissionCache</code> in [Parser/core/pipeline.py](file:///c:/Users/oksbw/Desktop/Workspace/Wealthfam/Parser/core/pipeline.py).</li><li><strong>Mechanism</strong>: Thread-safe sliding-window cache storing <code>SHA-256(tenant_id:source:content)</code> with a 5-minute TTL (max 5,000 entries).</li><li><strong>Purpose</strong>: Instantly deflects network retries from mobile background listeners or email sync pollers without touching disk or allocating database locks.</li><li><strong>Outcome</strong>: Returns <code>status: &quot;duplicate_submission&quot;</code> in $\\approx 0.05$ ms.</li></ul><h3 id="tier-2-authoritative-financial-ledger-deduplication-backend-postgresql" tabindex="-1">Tier 2: Authoritative Financial Ledger Deduplication (Backend PostgreSQL) <a class="header-anchor" href="#tier-2-authoritative-financial-ledger-deduplication-backend-postgresql" aria-label="Permalink to &quot;Tier 2: Authoritative Financial Ledger Deduplication (Backend PostgreSQL)&quot;">​</a></h3><ul><li><strong>Component</strong>: <code>TransactionDeduplicator</code> in [Backend/app/modules/ingestion/deduplicator.py](file:///c:/Users/oksbw/Desktop/Workspace/Wealthfam/Backend/app/modules/ingestion/deduplicator.py).</li><li><strong>Mechanism</strong>: Multi-tier cross-source matching against persistent PostgreSQL ledger (<code>transactions</code> &amp; <code>pending_transactions</code> tables): <ol><li><strong>Normalized UTR / Reference ID</strong>: Strips prefixes and leading zeros (<code>normalize_ref_id</code>) to match identical banking references.</li><li><strong>Canonical Content Hash</strong>: Generates <code>MD5(tenant_id:account_id:date:amount:type:normalized_vendor)</code>. Uses <code>date.date()</code> so that an SMS alert and an Email alert arriving at different timestamps produce the exact same hash.</li><li><strong>Resilient 3-Day Window &amp; Fuzzy Vendor</strong>: Checks <code>[date - 1d, date, date + 1d]</code>, matches exact monetary amount, and verifies token-intersection fuzzy merchant matching across descriptions.</li><li><strong>Geolocation Enrichment</strong>: If an incoming duplicate SMS carries GPS coordinates (<code>latitude</code>, <code>longitude</code>) from the Android background listener, the backend retroactively updates the existing ledger transaction rather than discarding the metadata.</li></ol></li></ul><hr><h2 id="_3-observability-operations-architecture" tabindex="-1">3. Observability &amp; Operations Architecture <a class="header-anchor" href="#_3-observability-operations-architecture" aria-label="Permalink to &quot;3. Observability &amp; Operations Architecture&quot;">​</a></h2><h3 id="_3-1-consumer-ingestion-feed-web-app-mobile-app" tabindex="-1">3.1 Consumer Ingestion Feed (<code>Web-App</code> &amp; <code>Mobile-App</code>) <a class="header-anchor" href="#_3-1-consumer-ingestion-feed-web-app-mobile-app" aria-label="Permalink to &quot;3.1 Consumer Ingestion Feed (`Web-App` &amp; `Mobile-App`)&quot;">​</a></h3><ul><li>Consumer users interact exclusively with the <strong>Backend</strong> (<code>:8000</code>).</li><li>Every ingested SMS and Email records its <code>raw_content</code> and plain-English <code>outcome</code> in PostgreSQL (<code>ingestion_events</code> and <code>email_sync_item_logs</code>).</li><li>Users manage personal Ignore/Allow rules and review triage items via <strong>Settings → Ingestions</strong> without ever seeing internal parser names, regex code, or container endpoints.</li></ul><h3 id="_3-2-operator-parser-studio-training-inbox-admin-web" tabindex="-1">3.2 Operator Parser Studio &amp; Training Inbox (<code>Admin-Web</code>) <a class="header-anchor" href="#_3-2-operator-parser-studio-training-inbox-admin-web" aria-label="Permalink to &quot;3.2 Operator Parser Studio &amp; Training Inbox (`Admin-Web`)&quot;">​</a></h3><ul><li>Dedicated administrative control plane on Port <code>8080</code> / <code>:5174</code>, backed by <code>Admin-Backend</code> (<code>:8002</code>) and <code>telemetry.duckdb</code>.</li><li><strong>Native Registry Inspector</strong>: Inspects all 23+ built-in bank parsers and their live regex patterns.</li><li><strong>Interactive Sandbox</strong>: Safely tests SMS, Email text, and password-protected PDF bank statements without writing to production ledgers.</li><li><strong>Training Inbox</strong>: Displays user-submitted unrecognized alerts, strictly scrubbed of personal PII via <code>FormatPreservingAnonymizer</code> before presentation.</li></ul><h3 id="_3-3-batch-processing-engine-batchingestionpipeline" tabindex="-1">3.3 Batch Processing Engine (<code>BatchIngestionPipeline</code>) <a class="header-anchor" href="#_3-3-batch-processing-engine-batchingestionpipeline" aria-label="Permalink to &quot;3.3 Batch Processing Engine (`BatchIngestionPipeline`)&quot;">​</a></h3><ul><li>High-throughput chunked ingestion (<code>POST /v1/ingest/batch</code>) designed for email sweep batches (50+ items).</li><li><strong>Defensive Input Coercion</strong>: Automatically strips and coerces <code>None</code> values for <code>subject</code>, <code>sender</code>, and <code>content</code>, preventing runtime crashes when client JSON payloads carry <code>null</code> fields.</li><li><strong>Sender Domain Verification</strong>: Dispatches <code>sender</code> to <code>p.can_handle(subject, content, sender=sender)</code> for all bank email parsers (e.g. IDBI, PNB, Canara, BoI, AU Bank) to confirm genuine sender authenticity.</li><li><strong>Date Hint Forwarding</strong>: Converts <code>received_at</code> timestamps into <code>date_hint</code> objects, allowing parsers to accurately resolve incomplete bank alert dates lacking year or seconds.</li></ul><hr><h2 id="_4-multi-tenancy-data-isolation" tabindex="-1">4. Multi-Tenancy &amp; Data Isolation <a class="header-anchor" href="#_4-multi-tenancy-data-isolation" aria-label="Permalink to &quot;4. Multi-Tenancy &amp; Data Isolation&quot;">​</a></h2><ul><li><strong>Stateless Parser</strong>: Zero customer data at rest. Operates globally for all tenants using stateless HTTP request/response payloads with short-lived JWT authentication.</li><li><strong>Backend Ledger</strong>: Every transaction, account, category rule, and merchant alias is strictly isolated by <code>tenant_id</code> in PostgreSQL with row-level tenant filtering.</li></ul>',21))])}const x=r(g,[["render",u]]);export{k as __pageData,x as default};
